531→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
532→// Returns the redacted transcript bytes so the caller can compute the content hash.
533→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
534→	// Redact secrets before chunking
535→	redacted, err := redact.JSONLBytes(transcript)
536→	if err != nil {
537→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
538→	}
539→
540→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
541→	if err != nil {
542→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
543→	}
544→
545→	for i, chunk := range chunks {
546→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
547→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
548→		if err != nil {
549→			return nil, err
550→		}
551→		entries[chunkPath] = object.TreeEntry{
552→			Name: chunkPath,
553→			Mode: filemode.Regular,
554→			Hash: blobHash,
555→		}
556→	}
557→
558→	return redacted, nil
559→}
